/** Explicit probes use only generated test text, never course files or credentials in output. */
@Service
public class RuntimeModelCapabilityService {
    public record ModelStatus(String role, String configuration, String model,
                              int declaredContextWindowTokens, boolean adapterImplemented) {}
    public record Check(String name, String status, String detail, long latencyMs, int testedCharacters) {}
    public record ProbeReport(String role, String status, List<Check> checks) {}
    private final RuntimeModelProperties properties;
    private final OpenAiChatModel generation;
    private final OpenAiChatModel planning;
    private final RagEmbeddingClient embedding;
    private final ObjectMapper mapper;

    public RuntimeModelCapabilityService(RuntimeModelProperties properties,
            @Qualifier("generationChatModel") OpenAiChatModel generation,
            @Qualifier("planningChatModel") OpenAiChatModel planning,
            RagEmbeddingClient embedding, ObjectMapper mapper) {
        this.properties=properties; this.generation=generation; this.planning=planning; this.embedding=embedding; this.mapper=mapper;
    }

    /** No network activity and no endpoint/key field. Configuration does not establish capability. */
    public List<ModelStatus> status() {
        return List.of("generation","planning","embedding","ocr").stream().map(role -> {
            var endpoint=properties.endpoint(role);
            return new ModelStatus(role,RuntimeModelPolicy.status(endpoint),endpoint.getModel(),
                    endpoint.getContextWindowTokens(),!role.equals("ocr"));
        }).toList();
    }

    public ProbeReport probe(String role) {
        var endpoint=properties.endpoint(role);
        String configured=RuntimeModelPolicy.status(endpoint);
        if (!configured.equals("CONFIGURED_UNVERIFIED")) return skipped(role,configured);
        if (role.equals("ocr")) return skipped(role,"OCR_ADAPTER_PENDING_K02");
        if (role.equals("embedding")) {
            var check=check("EMBEDDING",0,()->{
                var vectors=embedding.embed(List.of("K00 模型连通性检查"));
                return vectors.size()==1 && vectors.getFirst().length>0;
            });
            return new ProbeReport(role,check.status(),List.of(check));
        }
        OpenAiChatModel model=role.equals("generation")?generation:planning;
        var checks=new ArrayList<Check>();
        checks.add(check("TEXT",0,()->"ok".equals(content(model.call(prompt("Reply with exactly: ok",false))).strip())));
        if (!checks.getFirst().status().equals("PASS")) {
            for(String name:List.of("JSON_OBJECT","STREAM","CONTEXT_SAMPLE"))
                checks.add(new Check(name,"SKIPPED","TEXT_PROBE_FAILED",0,0));
            return new ProbeReport(role,"FAIL",List.copyOf(checks));
        }
        checks.add(check("JSON_OBJECT",0,()->{
            String text=content(model.call(prompt("Return JSON only: {\"ok\":true}",true)));
            try { var value=mapper.readTree(text); return value.isObject() && value.path("ok").isBoolean() && value.path("ok").asBoolean(); }
            catch(Exception e) { return false; }
        }));
        checks.add(check("STREAM",0,()->{
            var chunks=model.stream(prompt("Reply with exactly: ok",false)).take(128)
                    .collectList().block(Duration.ofSeconds(Math.max(1,endpoint.getTimeoutSeconds())));
            return chunks!=null && "ok".equals(chunks.stream().map(this::content).reduce("",String::concat).strip());
        }));
        String sentinel="K00_SENTINEL_"+UUID.randomUUID().toString().replace("-","");
        String context=sentinel+"\n"+"课程资料中的普通测试段落。".repeat(180)+"\n"+sentinel;
        checks.add(check("CONTEXT_SAMPLE",context.length(),()->sentinel.equals(content(model.call(prompt(
                "Read the following sample and return only its K00_SENTINEL identifier, with no explanation.\n"+context,false))).strip())));
        return new ProbeReport(role,checks.stream().allMatch(c->c.status().equals("PASS"))?"PASS":"FAIL",List.copyOf(checks));
    }

    private Prompt prompt(String text,boolean json) {
        var options=OpenAiChatOptions.builder().maxTokens(100).temperature(0.0);
        if(json) options.responseFormat(new ResponseFormat(ResponseFormat.Type.JSON_OBJECT,null));
        return new Prompt(text,options.build());
    }
    private String content(ChatResponse response) {
        return response==null || response.getResult()==null || response.getResult().getOutput()==null
                || response.getResult().getOutput().getContent()==null ? "" : response.getResult().getOutput().getContent();
    }
    private Check check(String name,int characters,Supplier<Boolean> run) {
        long started=System.nanoTime();
        String state="PASS",detail="OBSERVED_AT_TESTED_SIZE_ONLY";
        try { if(!run.get()) {state="FAIL";detail="UNEXPECTED_RESPONSE";} }
        catch(Exception e) {state="FAIL";detail=e instanceof ModelConfigurationException config?config.code():
                e instanceof ModelInvocationException invocation?invocation.code():"MODEL_CALL_FAILED";}
        return new Check(name,state,detail,Duration.ofNanos(System.nanoTime()-started).toMillis(),characters);
    }
    private ProbeReport skipped(String role,String code) { return new ProbeReport(role,"SKIPPED",List.of(new Check("CONFIGURATION","SKIPPED",code,0,0))); }
}
package com.cupk.aiacademy.model;

import org.springframework.ai.chat.model.ChatResponse;
import org.springframework.ai.chat.prompt.Prompt;
import org.springframework.ai.openai.OpenAiChatModel;
import org.springframework.ai.openai.OpenAiChatOptions;
import org.springframework.ai.openai.api.OpenAiApi;
import org.springframework.retry.support.RetryTemplate;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;
import org.springframework.web.client.RestClientResponseException;
import org.springframework.web.reactive.function.client.WebClientResponseException;

import java.time.Duration;

/** Keeps existing business injection points on one checked, compatible transport. */
public class GuardedChatModel extends OpenAiChatModel {
    private final RuntimeModelProperties.Endpoint endpoint;
    public GuardedChatModel(OpenAiApi api, RuntimeModelProperties.Endpoint endpoint) {
        super(api, OpenAiChatOptions.builder().model(endpoint.getModel().isBlank()
                        ? "MODEL_NOT_CONFIGURED" : endpoint.getModel()).build(),
                null, RetryTemplate.builder().maxAttempts(1).build());
        this.endpoint = endpoint;
    }
    private void check(Prompt prompt) {
        RuntimeModelPolicy.requireReady(endpoint, prompt.getOptions() == null ? null : prompt.getOptions().getModel());
    }
    @Override public ChatResponse call(Prompt prompt) {
        check(prompt);
        try { return super.call(prompt); } catch(RuntimeException e) { throw safeFailure(e); }
    }
    @Override public ChatResponse internalCall(Prompt prompt, ChatResponse previous) {
        check(prompt);
        try { return super.internalCall(prompt,previous); } catch(RuntimeException e) { throw safeFailure(e); }
    }
    @Override public Flux<ChatResponse> stream(Prompt prompt) {
        return deadline(Flux.defer(() -> { check(prompt); return super.stream(prompt); }));
    }
    @Override public Flux<ChatResponse> internalStream(Prompt prompt, ChatResponse previous) {
        return deadline(Flux.defer(() -> { check(prompt); return super.internalStream(prompt,previous); }));
    }
    private Flux<ChatResponse> deadline(Flux<ChatResponse> response) {
        return response.takeUntilOther(Mono.delay(Duration.ofSeconds(Math.max(1,endpoint.getTimeoutSeconds())))
                        .flatMap(tick->Mono.error(new ModelInvocationException("MODEL_TIMEOUT"))))
                .onErrorMap(this::safeFailure);
    }
    private RuntimeException safeFailure(Throwable error) {
        if(error instanceof ModelConfigurationException config) return config;
        if(error instanceof ModelInvocationException invocation) return invocation;
        String code="MODEL_CALL_FAILED";
        if(error instanceof RestClientResponseException response) code="MODEL_HTTP_"+response.getStatusCode().value();
        else if(error instanceof WebClientResponseException response) code="MODEL_HTTP_"+response.getStatusCode().value();
        else if(error instanceof java.util.concurrent.TimeoutException) code="MODEL_TIMEOUT";
        return new ModelInvocationException(code);
    }
}
package com.cupk.aiacademy.model;

import org.springframework.ai.openai.OpenAiChatModel;
import org.springframework.ai.openai.api.OpenAiApi;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Primary;
import org.springframework.http.client.JdkClientHttpRequestFactory;
import org.springframework.web.client.DefaultResponseErrorHandler;
import org.springframework.web.client.RestClient;
import org.springframework.web.reactive.function.client.WebClient;

import java.net.http.HttpClient;
import java.time.Duration;

@Configuration
@EnableConfigurationProperties(RuntimeModelProperties.class)
public class RuntimeModelConfiguration {
    @Bean @Primary
    public OpenAiChatModel generationChatModel(RuntimeModelProperties properties) { return create(properties.getGeneration()); }
    @Bean
    public OpenAiChatModel planningChatModel(RuntimeModelProperties properties) { return create(properties.getPlanning()); }

    private OpenAiChatModel create(RuntimeModelProperties.Endpoint endpoint) {
        // Invalid/missing settings may start the application; the guard rejects every call before I/O.
        boolean ready = "CONFIGURED_UNVERIFIED".equals(RuntimeModelPolicy.status(endpoint));
        String base = ready ? endpoint.getBaseUrl().replaceAll("/+$", "") : "http://127.0.0.1:1";
        String path = base.endsWith("/v1") ? "/chat/completions" : "/v1/chat/completions";
        var duration = Duration.ofSeconds(Math.max(1, endpoint.getTimeoutSeconds()));
        var factory = new JdkClientHttpRequestFactory(HttpClient.newBuilder().connectTimeout(duration).build());
        factory.setReadTimeout(duration);
        var api = new OpenAiApi(base, ready ? endpoint.getApiKey() : "NOT_CONFIGURED", path, "/v1/embeddings",
                RestClient.builder().requestFactory(factory), WebClient.builder(), new DefaultResponseErrorHandler());
        return new GuardedChatModel(api, endpoint);
    }
}
package com.cupk.aiacademy.model;

import java.net.URI;
import java.util.Locale;
import java.util.Set;

public final class RuntimeModelPolicy {
    private RuntimeModelPolicy() {}

    public static String status(RuntimeModelProperties.Endpoint endpoint) {
        try { requireReady(endpoint, null); return "CONFIGURED_UNVERIFIED"; }
        catch (ModelConfigurationException e) { return e.code(); }
    }

    public static void requireReady(RuntimeModelProperties.Endpoint endpoint, String requestedModel) {
        if (!endpoint.isEnabled()) throw new ModelConfigurationException("MODEL_DISABLED");
        if (endpoint.getBaseUrl().isBlank() || endpoint.getModel().isBlank()
                || endpoint.getApiKey().isBlank() || "NOT_CONFIGURED".equals(endpoint.getApiKey()))
            throw new ModelConfigurationException("MODEL_NOT_CONFIGURED");
        URI uri;
        try {
            uri = URI.create(endpoint.getBaseUrl());
            String host = uri.getHost();
            if (host == null || uri.getUserInfo() != null || uri.getQuery() != null || uri.getFragment() != null
                    || !("https".equalsIgnoreCase(uri.getScheme()) || ("http".equalsIgnoreCase(uri.getScheme())
                    && Set.of("localhost", "127.0.0.1", "::1", "[::1]").contains(host.toLowerCase(Locale.ROOT)))))
                throw new IllegalArgumentException();
        } catch (IllegalArgumentException e) { throw new ModelConfigurationException("MODEL_ENDPOINT_INVALID"); }
        String host = uri.getHost().toLowerCase(Locale.ROOT).replaceAll("\\.+$", "");
        if (host.equals("openai.com") || host.endsWith(".openai.com") || blockedModel(endpoint.getModel())
                || (requestedModel != null && !requestedModel.isBlank() && blockedModel(requestedModel)))
            throw new ModelConfigurationException("MODEL_BLOCKED");
    }

    private static boolean blockedModel(String model) {
        String value = model.strip().toLowerCase(Locale.ROOT);
        for (String part : value.split("[/.:]")) {
            if (part.equals("openai") || part.startsWith("gpt") || part.startsWith("chatgpt")
                    || part.matches("o[134](-.*)?") || part.startsWith("text-embedding-")
                    || part.startsWith("text-davinci") || part.startsWith("davinci")) return true;
        }
        return false;
    }
}
