        assertEquals(2, hit.page());
        assertTrue(hit.content().contains("Photosynthesis"));
        assertFalse(hit.content().contains("Gradient descent"), "Chunks must not merge different PDF pages");
        assertEquals(2, hit.ordinal());
    }

